// Function node
// Input: many items (one per member)
// Output: 1 item with { rows: [...] } ready for Supabase
const nullIfEmpty = v => (v === '' ? null : v);

function normalize(j) {
  return Object.fromEntries(
    Object.entries({
      user_id: j.user_id,
      first_name: j.first_name,
      last_name: j.last_name,
      email: j.email,
      cell_phone: j.cell_phone,
      gender: j.gender,
      scout: j.scout,
      current_position: j.current_position,
      current_rank: j.current_rank,

      // date-like fields: "" -> null
      born_on: nullIfEmpty(j.born_on),
      PartA: nullIfEmpty(j.PartA),
      PartB: nullIfEmpty(j.PartB),
      PartC: nullIfEmpty(j.PartC),
      date_joined: nullIfEmpty(j.date_joined),

      money_account_balance: j.money_account_balance,
      user_name: j.user_name,
      txtOptOut: j.txtOptOut,
      BSA_id: j.BSA_id,
      allergies: j.allergies,
    }).filter(([, v]) => v !== undefined)
  );
}

const rows = items.map(i => normalize(i.json));
return [{ json: { rows } }];

// Function node
// Input: items like { user_id, patrol_id: [113082, 113083], ... }
// Output: 1 item with { rows: [ {user_id, patrol_id}, ... ] }

const rows = [];
const seen = new Set(); // de-dupe across all inputs

for (const { json } of items) {
  const uid = json.user_id;
  const plist = Array.isArray(json.patrol_id) ? json.patrol_id : [];

  for (const p of plist) {
    // normalize patrol_id to integer (or skip if invalid)
    const pid = Number(p);
    if (!Number.isFinite(pid)) continue;

    const key = `${uid}::${pid}`;
    if (seen.has(key)) continue;
    seen.add(key);

    rows.push({ user_id: uid, patrol_id: pid });
  }
}

return [{ json: { rows } }];

