const items = $input.all();

const rows = [];
const seen = new Set();

// Remove any "(...)" segments, collapse spaces, trim
function cleanName(name) {
  if (name == null) return null;
  const s = String(name)
    .replace(/\s*\([^)]*\)\s*/g, ' ') // drop all parenthetical chunks
    .replace(/\s+/g, ' ')             // collapse multiple spaces
    .trim();
  return s || null;
}

for (const { json } of items) {
  const uid = json.user_id;
  const ranks = Array.isArray(json.ranks) ? json.ranks : [];

  for (const r of ranks) {
    const completed_on = r.completed_on === '' ? null : r.completed_on;

    // Clone & clean name
    const rr = { ...r };
    rr.name = cleanName(r.name);

    // Build a stable dedupe key (prefer IDs; fall back to cleaned name)
    const idPart = rr.user_achievement_id ?? rr.achievement_id ?? rr.name ?? '';
    const key = `${uid}::${idPart}`;
    if (seen.has(key)) continue;
    seen.add(key);

    rows.push({ user_id: uid, ...rr, completed_on });
  }
}

return [{ json: { rows } }];

